INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_basic#10','kor',1,2,'u5','L04','g1_2_kor_u5_L04_basic','lesson_basic','K1-2-u5-C3',3,'error','auto','「밤」의 받침만 바꾼 낱말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#1','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',2,'mc','auto','「물」의 한 자리를 바꾸어 만든 글자 가운데 뜻이 없는 것은 어느 것인가요?',ARRAY['K1-2-u5-X07']::text[],false,'{"seq":1,"concept":"K1-2-u5-C3","difficulty":2,"kind":"mc","stem":"「물」의 한 자리를 바꾸어 만든 글자 가운데 뜻이 없는 것은 어느 것인가요?","options":[{"t":"뭏","correct":true},{"t":"불","mis":"K1-2-u5-X07"},{"t":"줄","mis":"K1-2-u5-X07"}],"explanation":["「뭏」은 소리만 나고 뜻이 없어요.","불과 줄은 뜻이 있는 낱말이에요.","그 낱말을 그림으로 그릴 수 있나 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#2','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',2,'mc','auto','「공」의 모음자만 바꾼 낱말은 어느 것인가요?',ARRAY['K1-2-u5-X01']::text[],true,'{"seq":2,"concept":"K1-2-u5-C3","difficulty":2,"kind":"mc","stem":"「공」의 모음자만 바꾼 낱말은 어느 것인가요?","options":[{"t":"강","correct":true},{"t":"콩","mis":"K1-2-u5-X01"},{"t":"곰","mis":"K1-2-u5-X01"}],"explanation":["ㅗ를 ㅏ로 바꾸면 강이에요.","콩은 첫 자음자를, 곰은 받침을 바꾸었어요.","가운데 소리만 달라요."],"variant_rule":{"alt":[{"stem":"「손」의 받침만 바꾼 낱말은 어느 것인가요?","options":[{"t":"솜","correct":true},{"t":"산","mis":"K1-2-u5-X01"},{"t":"돈","mis":"K1-2-u5-X01"}],"explanation":["ㄴ을 ㅁ으로 바꾸면 솜이에요.","산은 모음자를, 돈은 첫 자음자를 바꾸었어요.","끝소리만 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u5_L04_challenge#3','kor',1,2,'u5','L04','g1_2_kor_u5_L04_challenge','lesson_challenge','K1-2-u5-C3',3,'mc','auto','「공」을 「콩」으로 바꾸었더니 무엇이 달라졌나요?',ARRAY['K1-2-u5-X03']::text[],false,'{"seq":3,"concept":"K1-2-u5-C3","difficulty":3,"kind":"mc","stem":"「공」을 「콩」으로 바꾸었더니 무엇이 달라졌나요?","options":[{"t":"소리와 뜻이 모두 달라졌다","correct":true},{"t":"소리만 달라지고 뜻은 같다","mis":"K1-2-u5-X03"},{"t":"뜻만 달라지고 소리는 같다","mis":"K1-2-u5-X03"}],"explanation":["놀이하는 공이 먹는 콩이 되었어요.","소리도 [공]에서 [콩]으로 달라졌어요.","한 자리가 소리와 뜻을 모두 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
