INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L06_challenge#8','math',1,2,'u1','L06','g1_2_math_u1_L06_challenge','lesson_challenge','M1-2-u1-C5',4,'sa','auto','86과 90 사이에 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u1-C5","difficulty":4,"kind":"sa","stem":"86과 90 사이에 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["87, 88, 89가 사이에 있어요.","모두 3개예요.","양 끝의 86과 90은 세지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
