INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L08_challenge#7','math',1,2,'u1','L08','g1_2_math_u1_L08_challenge','lesson_challenge','M1-2-u1-C7',3,'mc','auto','11보다 크고 15보다 작은 짝수는 무엇인가요?',ARRAY['M1-2-u1-X09']::text[],false,'{"seq":7,"concept":"M1-2-u1-C7","difficulty":3,"kind":"mc","stem":"11보다 크고 15보다 작은 짝수는 무엇인가요?","options":[{"t":"12와 14","correct":true},{"t":"13","mis":"M1-2-u1-X09"},{"t":"12만","mis":"M1-2-u1-X09"}],"explanation":["11과 15 사이의 수는 12, 13, 14예요.","이 중 짝수는 12와 14예요.","13은 하나가 남아 홀수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L08_challenge#8','math',1,2,'u1','L08','g1_2_math_u1_L08_challenge','lesson_challenge','M1-2-u1-C7',4,'sa','auto','둘씩 짝을 지으면 하나가 남는 수 중에서 10보다 크고 13보다 작은 수를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u1-C7","difficulty":4,"kind":"sa","stem":"둘씩 짝을 지으면 하나가 남는 수 중에서 10보다 크고 13보다 작은 수를 쓰세요.","answer":["11"],"explanation":["10과 13 사이의 수는 11, 12예요.","하나가 남는 수는 홀수예요.","11이 홀수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L08_challenge#9','math',1,2,'u1','L08','g1_2_math_u1_L08_challenge','lesson_challenge','M1-2-u1-C7',4,'mc','auto','학생 19명이 두 명씩 짝을 지으면 어떻게 되나요?',ARRAY['M1-2-u1-X09']::text[],false,'{"seq":9,"concept":"M1-2-u1-C7","difficulty":4,"kind":"mc","stem":"학생 19명이 두 명씩 짝을 지으면 어떻게 되나요?","options":[{"t":"한 명이 남아요","correct":true},{"t":"남는 사람이 없어요","mis":"M1-2-u1-X09"},{"t":"두 명이 남아요","mis":"M1-2-u1-X09"}],"explanation":["19를 둘씩 짝지어 보세요.","한 명이 남아요.","그래서 19는 홀수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L08_challenge#10','math',1,2,'u1','L08','g1_2_math_u1_L08_challenge','lesson_challenge','M1-2-u1-C7',4,'essay','teacher','우리 반 학생 수가 짝수인지 홀수인지 알아보는 방법을 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u1-C7","difficulty":4,"kind":"essay","stem":"우리 반 학생 수가 짝수인지 홀수인지 알아보는 방법을 말해 보세요.","answer_guide":"「두 명씩 짝을 지어 남는 사람이 있는지 본다」는 방법이 나오면 통과. 실제 반 학생 수를 넣어 말하면 더 좋다.","explanation":["두 명씩 짝을 지어 보세요.","남는 사람이 없으면 짝수예요.","한 명이 남으면 홀수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_a#1','math',1,2,'u1','review','g1_2_math_u1_review_a','unit_review','M1-2-u1-C1',1,'mc','auto','그림을 보세요. 얼마인가요?',ARRAY['M1-2-u1-X02','M1-2-u1-X01']::text[],true,'{"seq":1,"concept":"M1-2-u1-C1","difficulty":1,"kind":"mc","stem":"그림을 보세요. 얼마인가요?","asset":{"type":"bundle_ones","tens":6,"ones":0},"options":[{"t":"60","correct":true},{"t":"6","mis":"M1-2-u1-X02"},{"t":"16","mis":"M1-2-u1-X01"}],"explanation":["10개씩 묶음이 6개예요.","묶음 6개는 60이에요.","묶음 하나는 낱개 10개와 같아요."],"variant_rule":{"bundle":{"tens":[6,9],"ones":[0,0],"ask":"number"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_a#2','math',1,2,'u1','review','g1_2_math_u1_review_a','unit_review','M1-2-u1-C2',1,'sa','auto','그림이 나타내는 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u1-C2","difficulty":1,"kind":"sa","stem":"그림이 나타내는 수를 숫자로 쓰세요.","asset":{"type":"bundle_ones","tens":4,"ones":3},"answer":["43"],"explanation":["묶음 4개는 40이에요.","낱개 3개를 더하면 43이에요.","묶음 수를 앞에, 낱개 수를 뒤에 써요."],"variant_rule":{"bundle":{"tens":[2,9],"ones":[1,9],"ask":"number"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
