INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_a#4','math',1,2,'u1','review','g1_2_math_u1_review_a','unit_review','M1-2-u1-C5',1,'sa','auto','수 배열판이에요. 빈칸에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u1-C5","difficulty":1,"kind":"sa","stem":"수 배열판이에요. 빈칸에 알맞은 수를 쓰세요.","asset":{"type":"hundred_chart","cells":[61,62,null,64,65,66],"cols":6},"answer":["63"],"explanation":["한 칸 갈 때마다 1씩 커져요.","62 다음은 63이에요.","앞뒤 칸을 보고 이어 세어요."],"variant_rule":{"chart":{"from":21,"to":94}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
