INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_a#9','math',1,2,'u1','review','g1_2_math_u1_review_a','unit_review','M1-2-u1-C1',2,'sa','auto','10개씩 묶음 8개는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M1-2-u1-C1","difficulty":2,"kind":"sa","stem":"10개씩 묶음 8개는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"bundle_ones","tens":8,"ones":0},"answer":["80"],"explanation":["묶음 하나는 10이에요.","묶음 8개는 80이에요.","여든(이)라고도 읽어요."],"variant_rule":{"bundle":{"tens":[6,9],"ones":[0,0],"ask":"number"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
