INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_a#17','math',1,2,'u1','review','g1_2_math_u1_review_a','unit_review','M1-2-u1-C2',3,'mc','auto','10개씩 묶음 3개와 낱개 12개는 얼마인가요?',ARRAY['M1-2-u1-X03','M1-2-u1-X01']::text[],false,'{"seq":17,"concept":"M1-2-u1-C2","difficulty":3,"kind":"mc","stem":"10개씩 묶음 3개와 낱개 12개는 얼마인가요?","options":[{"t":"42","correct":true},{"t":"32","mis":"M1-2-u1-X03"},{"t":"312","mis":"M1-2-u1-X01"}],"explanation":["낱개 12개에서 10개를 묶어요.","묶음 4개와 낱개 2개가 되어 42예요.","낱개는 9개까지만 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_a#18','math',1,2,'u1','review','g1_2_math_u1_review_a','unit_review','M1-2-u1-C5',3,'sa','auto','수를 거꾸로 세었어요. 빈칸에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M1-2-u1-C5","difficulty":3,"kind":"sa","stem":"수를 거꾸로 세었어요. 빈칸에 알맞은 수를 쓰세요.","asset":{"type":"hundred_chart","cells":[90,89,88,null,86,85],"cols":6},"answer":["87"],"explanation":["거꾸로 세면 1씩 작아져요.","88 다음은 87이에요.","앞뒤 칸을 보고 세어요."],"variant_rule":{"chart":{"from":31,"to":96,"dir":"back"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
