INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_c#12','math',1,2,'u1','review','g1_2_math_u1_review_c','unit_review','M1-2-u1-C5',2,'mc','auto','89보다 1만큼 더 큰 수는 얼마인가요?',ARRAY['M1-2-u1-X06','M1-2-u1-X05']::text[],false,'{"seq":12,"concept":"M1-2-u1-C5","difficulty":2,"kind":"mc","stem":"89보다 1만큼 더 큰 수는 얼마인가요?","options":[{"t":"90","correct":true},{"t":"99","mis":"M1-2-u1-X06"},{"t":"80","mis":"M1-2-u1-X05"}],"explanation":["낱개 9에 1을 더하면 10이에요.","낱개 10개를 묶으면 묶음이 하나 늘어요.","그래서 90이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
