INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_c#14','math',1,2,'u1','review','g1_2_math_u1_review_c','unit_review','M1-2-u1-C7',2,'ox','auto','둘씩 짝을 지어 보았어요. 17은 짝수입니다.',ARRAY['M1-2-u1-X09']::text[],true,'{"seq":14,"concept":"M1-2-u1-C7","difficulty":2,"kind":"ox","stem":"둘씩 짝을 지어 보았어요. 17은 짝수입니다.","asset":{"type":"pair_row","n":17},"answer":"X","reason_options":[{"t":"둘씩 짝지으면 하나가 남으니까","correct":true},{"t":"수가 크니까","mis":"M1-2-u1-X09"}],"explanation":["17을 둘씩 짝지어 보세요.","하나가 남으니 홀수예요.","남는 것이 있으면 홀수예요."],"variant_rule":{"parity":{"range":[3,19]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
