INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_d#6','math',1,2,'u1','review','g1_2_math_u1_review_d','unit_review','M1-2-u1-C7',1,'mc','auto','둘씩 짝을 지었어요. 14는 짝수인가요, 홀수인가요?',ARRAY['M1-2-u1-X09']::text[],true,'{"seq":6,"concept":"M1-2-u1-C7","difficulty":1,"kind":"mc","stem":"둘씩 짝을 지었어요. 14는 짝수인가요, 홀수인가요?","asset":{"type":"pair_row","n":14},"options":[{"t":"짝수","correct":true},{"t":"홀수","mis":"M1-2-u1-X09"}],"explanation":["14를 둘씩 짝지어 보세요.","남는 것이 없으니 짝수예요.","크기와는 관계없어요."],"variant_rule":{"parity":{"range":[4,20]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_d#7','math',1,2,'u1','review','g1_2_math_u1_review_d','unit_review','M1-2-u1-C2',1,'mc','auto','그림에서 10개씩 묶음은 몇 개인가요?',ARRAY['M1-2-u1-X01','M1-2-u1-X02']::text[],true,'{"seq":7,"concept":"M1-2-u1-C2","difficulty":1,"kind":"mc","stem":"그림에서 10개씩 묶음은 몇 개인가요?","asset":{"type":"bundle_ones","tens":8,"ones":4},"options":[{"t":"8","correct":true},{"t":"4","mis":"M1-2-u1-X01"},{"t":"84","mis":"M1-2-u1-X02"}],"explanation":["묶음만 세어요.","묶음은 8개예요.","4은(는) 낱개의 수예요."],"variant_rule":{"bundle":{"tens":[2,9],"ones":[1,9],"ask":"tens"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
