INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_d#9','math',1,2,'u1','review','g1_2_math_u1_review_d','unit_review','M1-2-u1-C1',2,'sa','auto','10개씩 묶음 7개는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M1-2-u1-C1","difficulty":2,"kind":"sa","stem":"10개씩 묶음 7개는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"bundle_ones","tens":7,"ones":0},"answer":["70"],"explanation":["묶음 하나는 10이에요.","묶음 7개는 70이에요.","일흔(이)라고도 읽어요."],"variant_rule":{"bundle":{"tens":[6,9],"ones":[0,0],"ask":"number"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_d#10','math',1,2,'u1','review','g1_2_math_u1_review_d','unit_review','M1-2-u1-C2',2,'mc','auto','10개씩 묶음 2개와 낱개 8개는 얼마인가요?',ARRAY['M1-2-u1-X01','M1-2-u1-X02']::text[],false,'{"seq":10,"concept":"M1-2-u1-C2","difficulty":2,"kind":"mc","stem":"10개씩 묶음 2개와 낱개 8개는 얼마인가요?","options":[{"t":"28","correct":true},{"t":"82","mis":"M1-2-u1-X01"},{"t":"10","mis":"M1-2-u1-X02"}],"explanation":["묶음 2개는 20이에요.","낱개 8개를 더하면 28이에요.","묶음이 앞, 낱개가 뒤예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
