INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_d#17','math',1,2,'u1','review','g1_2_math_u1_review_d','unit_review','M1-2-u1-C2',3,'mc','auto','10개씩 묶음 5개와 낱개 14개는 얼마인가요?',ARRAY['M1-2-u1-X03','M1-2-u1-X01']::text[],false,'{"seq":17,"concept":"M1-2-u1-C2","difficulty":3,"kind":"mc","stem":"10개씩 묶음 5개와 낱개 14개는 얼마인가요?","options":[{"t":"64","correct":true},{"t":"54","mis":"M1-2-u1-X03"},{"t":"514","mis":"M1-2-u1-X01"}],"explanation":["낱개 14개에서 10개를 묶어요.","묶음 6개와 낱개 4개가 되어 64예요.","낱개는 9개까지만 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
