INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_d#22','math',1,2,'u1','review','g1_2_math_u1_review_d','unit_review','M1-2-u1-C5',3,'mc','auto','99보다 1만큼 더 큰 수는 얼마인가요?',ARRAY['M1-2-u1-X11']::text[],false,'{"seq":22,"concept":"M1-2-u1-C5","difficulty":3,"kind":"mc","stem":"99보다 1만큼 더 큰 수는 얼마인가요?","options":[{"t":"100","correct":true},{"t":"90","mis":"M1-2-u1-X11"},{"t":"991","mis":"M1-2-u1-X11"}],"explanation":["99는 묶음 9개와 낱개 9개예요.","낱개가 하나 늘면 묶음이 10개가 돼요.","묶음 10개는 100이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
