INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L06_challenge#1','math',1,2,'u2','L06','g1_2_math_u2_L06_challenge','lesson_challenge','M1-2-u2-C5',2,'sa','auto','십 배열판을 보세요. 10개에서 2개를 덜어 냈어요. 남은 것은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u2-C5","difficulty":2,"kind":"sa","stem":"십 배열판을 보세요. 10개에서 2개를 덜어 냈어요. 남은 것은 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"ten_frame","filled":8,"add":0},"answer":["8"],"explanation":["10칸에서 2칸을 덜어 냈어요.","남은 칸은 8칸이에요.","2와 8은 10이 되는 짝이에요."],"variant_rule":{"frame":{"filled":[1,9],"ask":"sub"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
