INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L07_challenge#1','math',1,2,'u2','L07','g1_2_math_u2_L07_challenge','lesson_challenge','M1-2-u2-C6',2,'sa','auto','5 + 5 + 7 은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M1-2-u2-C6","difficulty":2,"kind":"sa","stem":"5 + 5 + 7 은 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["5와 5를 더하면 10이에요.","10에 7을 더하면 17이에요.","10을 만든 뒤 남은 수를 더해요."],"variant_rule":{"maketen":{"pos":"front","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u2_L07_challenge#2','math',1,2,'u2','L07','g1_2_math_u2_L07_challenge','lesson_challenge','M1-2-u2-C6',2,'mc','auto','9 + 1 + 8 은 얼마인가요?',ARRAY['M1-2-u2-X08','M1-2-u2-X03']::text[],true,'{"seq":2,"concept":"M1-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 + 1 + 8 은 얼마인가요?","options":[{"t":"18","correct":true},{"t":"10","mis":"M1-2-u2-X08"},{"t":"17","mis":"M1-2-u2-X03"}],"explanation":["9와 1을 더하면 10이에요.","10에 8을 더하면 18이에요.","10에서 멈추면 안 돼요."],"variant_rule":{"maketen":{"pos":"front","last":[1,9]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
