INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X01','math',1,'u5',ARRAY['M1-2-u5-C1','M1-2-u5-C4','M1-2-u5-C6']::text[],'되풀이되는 부분을 처음이 아닌 중간부터 잡는다 — 「1, 1, 6」을 「1, 6, 1」로','되풀이되는 부분에 ○를 처음부터 묶게 하고 「처음 것부터」 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X02','math',1,'u5',ARRAY['M1-2-u5-C1','M1-2-u5-C2']::text[],'되풀이되는 부분의 길이를 잘못 잡는다 — 큰·작·작 을 큰·작 으로','묶음 표시를 한 뒤 묶음 안의 개수를 세어 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X03','math',1,'u5',ARRAY['M1-2-u5-C1']::text[],'무엇이 반복되는지 똑똑히 말하지 못한다 — 「의자가 여러 개 있어요」처럼 색·크기·모양을 짚지 않음','「무엇이(색·크기·모양) 어떻게 반복되나」 문장 틀로 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X04','math',1,'u5',ARRAY['M1-2-u5-C2','M1-2-u5-C6']::text[],'물건·색만 다르면 다른 규칙이라고 본다 — 풀·풀·가위 와 검정·검정·흰색이 다른 규칙','두 줄을 나란히 놓고 되풀이되는 부분의 길이·차례가 같은지 짝 지어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X05','math',1,'u5',ARRAY['M1-2-u5-C2','M1-2-u5-C3']::text[],'규칙이 없는 배열도 규칙이 있다고 본다 — 마음대로 놓아도 무늬','되풀이되는 부분에 ○를 해 보게 하고 묶음이 안 되면 규칙이 아님을 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X06','math',1,'u5',ARRAY['M1-2-u5-C4','M1-2-u5-C5']::text[],'몇씩 커지는지 보지 않고 늘 1씩 커진다고 본다 — 1, 3, 5 다음을 6','옆의 수와 차이를 뛰어 세기로 재어 「몇씩」을 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X07','math',1,'u5',ARRAY['M1-2-u5-C4']::text[],'작아지는 규칙을 커지는 것으로 읽는다 — 28, 26, 24 다음을 26','화살표로 방향을 표시하고 「몇부터 시작하여 몇씩 작아져요」 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X08','math',1,'u5',ARRAY['M1-2-u5-C5']::text[],'수 배열표에서 아래로 갈 때도 1씩 커진다고 본다 — 세로줄 10씩을 1씩','세로 한 줄을 손가락으로 짚으며 12→22→32 를 읽고 차이 재기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X09','math',1,'u5',ARRAY['M1-2-u5-C5']::text[],'비스듬한 줄·색칠한 수의 규칙을 못 잡는다 — 11씩·9씩·3씩을 10씩이나 1씩으로','색칠한 수만 따로 적어 옆 수와 차이를 재기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X10','math',1,'u5',ARRAY['M1-2-u5-C6']::text[],'수로 나타낼 때 짝짓기만 하고 되풀이를 살리지 않는다 — 🚲=2, 🛺=3 이라고만 하고 끝','같은 규칙을 그림·수·몸짓 세 줄로 나란히 쓰고 묶음이 같은지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X11','math',1,'u5',ARRAY['M1-2-u5-C2','M1-2-u5-C3']::text[],'되풀이 규칙으로 놓은 전체에서 한 물건의 개수를 한 덩이 안의 개수로 답한다 — 6개 중 지우개를 1개','덩이를 세어 「덩이 수 × 덩이 안 개수」로 다시 세어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#1','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',1,'mc','auto','안전 고깔이 줄지어 있어요. 빈칸에 올 고깔은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X03']::text[],true,'{"seq":1,"concept":"M1-2-u5-C1","difficulty":1,"kind":"mc","stem":"안전 고깔이 줄지어 있어요. 빈칸에 올 고깔은 무엇인가요?","asset":{"type":"pattern_row","items":["🔶","🔺","🔶","🔺","🔶","🔺",null]},"options":[{"t":"🔶","correct":true},{"t":"🔺","mis":"M1-2-u5-X01"},{"t":"🟦","mis":"M1-2-u5-X03"}],"variant_rule":{"repeat":{"ask":"next","unit":[2,2],"pool":["🔶","🔺","🟦","⭐","🟢","🍎"]}},"explanation":["🔶, 🔺 가 되풀이돼요.","🔺 다음이니 빈칸에는 🔶 가 와요.","되풀이되는 부분을 처음부터 묶어 보면 차례가 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#2','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',1,'mc','auto','그림에서 반복되는 부분은 어느 것인가요?',ARRAY['M1-2-u5-X02','M1-2-u5-X01']::text[],false,'{"seq":2,"concept":"M1-2-u5-C1","difficulty":1,"kind":"mc","stem":"그림에서 반복되는 부분은 어느 것인가요?","asset":{"type":"pattern_row","items":["🔶","🔺","🔶","🔺","🔶","🔺"]},"options":[{"t":"🔶 🔺","correct":true},{"t":"🔶 🔶 🔺","mis":"M1-2-u5-X02"},{"t":"🔺 🔶","mis":"M1-2-u5-X01"}],"explanation":["처음부터 보면 🔶 다음에 🔺 가 와요.","🔶, 🔺 두 개가 한 덩이로 되풀이돼요.","중간부터 묶으면 🔺, 🔶 처럼 차례가 뒤바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#3','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',1,'sa','auto','풍선이 둥근 풍선, 긴 풍선 차례로 6개 있어요. 둥근 풍선은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-2-u5-C1","difficulty":1,"kind":"sa","stem":"풍선이 둥근 풍선, 긴 풍선 차례로 6개 있어요. 둥근 풍선은 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"pattern_row","items":["🎈","🪅","🎈","🪅","🎈","🪅"]},"answer":["3"],"variant_rule":{"repeat":{"ask":"count","unit":[2,2],"pool":["🎈","🪅","🎀","🎁"]}},"explanation":["🎈, 🪅 가 되풀이돼요.","한 덩이에 🎈 가 1개, 덩이가 3개라 🎈 는 3개예요.","전체에서 세어야지 한 덩이 안의 수만 답하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#4','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',1,'ox','auto','필통의 꽃무늬에서 🌸, 🌺 가 반복됩니다.',ARRAY['M1-2-u5-X02']::text[],true,'{"seq":4,"concept":"M1-2-u5-C1","difficulty":1,"kind":"ox","stem":"필통의 꽃무늬에서 🌸, 🌺 가 반복됩니다.","asset":{"type":"pattern_row","items":["🌸","🌺","🌸","🌺","🌸","🌺"]},"answer":"O","reason_options":[{"t":"🌸 다음 🌺, 그다음 다시 🌸 니까","correct":true},{"t":"🌸, 🌸, 🌺 가 반복되니까","mis":"M1-2-u5-X02"}],"variant_rule":{"repeat":{"ask":"next","unit":[2,2],"pool":["🌸","🌺","🌼","🌷"]}},"explanation":["🌸 다음에 🌺, 그다음에 다시 🌸 가 와요.","🌸, 🌺 두 개가 한 덩이예요 — 맞아요.","한 덩이에 몇 개가 들어가는지 묶어서 세어 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#5','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',2,'mc','auto','화살표가 ↑, ↑, ↓, ↓ 로 반복돼요. 빈칸에 올 화살표는 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X03']::text[],false,'{"seq":5,"concept":"M1-2-u5-C1","difficulty":2,"kind":"mc","stem":"화살표가 ↑, ↑, ↓, ↓ 로 반복돼요. 빈칸에 올 화살표는 무엇인가요?","asset":{"type":"pattern_row","items":["↑","↑","↓","↓","↑","↑","↓",null]},"options":[{"t":"↓","correct":true},{"t":"↑","mis":"M1-2-u5-X01"},{"t":"→","mis":"M1-2-u5-X03"}],"explanation":["↑, ↑, ↓, ↓ 네 개가 한 덩이예요.","↑, ↑, ↓ 다음이니 ↓ 가 와요.","방향이 반복되는 규칙이에요 — 다른 방향은 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#6','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',2,'mc','auto','곰 얼굴이 바로, 거꾸로 반복돼요. 중간에 빠진 것은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X03']::text[],false,'{"seq":6,"concept":"M1-2-u5-C1","difficulty":2,"kind":"mc","stem":"곰 얼굴이 바로, 거꾸로 반복돼요. 중간에 빠진 것은 무엇인가요?","asset":{"type":"pattern_row","items":["🐻","🙃","🐻",null,"🐻","🙃"]},"options":[{"t":"🙃","correct":true},{"t":"🐻","mis":"M1-2-u5-X01"},{"t":"🐷","mis":"M1-2-u5-X03"}],"explanation":["🐻, 🙃 가 되풀이돼요.","🐻 다음 자리가 비었으니 🙃 가 와요.","앞뒤 그림을 보고 차례를 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#7','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',2,'match','auto','배열과 규칙을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u5-C1","difficulty":2,"kind":"match","stem":"배열과 규칙을 선으로 이어 보세요.","pairs":[{"l":"🔶 🔺 🔶 🔺","r":"🔶, 🔺 가 반복돼요"},{"l":"🧴 🩹 🩹 🧴 🩹 🩹","r":"🧴, 🩹, 🩹 가 반복돼요"},{"l":"↑ ↑ ↓ ↓ ↑ ↑ ↓ ↓","r":"↑, ↑, ↓, ↓ 가 반복돼요"}],"explanation":["처음부터 되풀이되는 부분을 묶어요.","🔶, 🔺 는 두 개, 🧴, 🩹, 🩹 는 세 개가 한 덩이예요.","↑, ↑, ↓, ↓ 는 네 개가 한 덩이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#8','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',2,'sa','auto','🍎, 🍎, 🍐 가 되풀이되는 규칙으로 9개를 놓았어요. 🍎 는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M1-2-u5-C1","difficulty":2,"kind":"sa","stem":"🍎, 🍎, 🍐 가 되풀이되는 규칙으로 9개를 놓았어요. 🍎 는 모두 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"pattern_row","items":["🍎","🍎","🍐","🍎","🍎","🍐","🍎","🍎","🍐"]},"answer":["6"],"variant_rule":{"repeat":{"ask":"count","unit":[3,3],"pool":["🍎","🍐","🍇","🍊"]}},"explanation":["한 덩이 🍎, 🍎, 🍐 에 🍎 가 2개 있어요.","9개면 덩이가 3개라 🍎 는 6개예요.","2는 한 덩이 안의 수 — 전체에서 세어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#9','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',2,'mc','auto','그림의 규칙을 가장 똑똑히 말한 것은 어느 것인가요?',ARRAY['M1-2-u5-X03','M1-2-u5-X02']::text[],false,'{"seq":9,"concept":"M1-2-u5-C1","difficulty":2,"kind":"mc","stem":"그림의 규칙을 가장 똑똑히 말한 것은 어느 것인가요?","asset":{"type":"pattern_row","items":["🧴","🧴","✂️","🧴","🧴","✂️"]},"options":[{"t":"풀, 풀, 가위가 반복돼요","correct":true},{"t":"물건이 여러 개 있어요","mis":"M1-2-u5-X03"},{"t":"풀, 가위가 반복돼요","mis":"M1-2-u5-X02"}],"explanation":["🧴 🧴 ✂️ 다음에 다시 🧴 🧴 ✂️ 가 와요.","「풀, 풀, 가위」 세 개가 한 덩이예요.","무엇이 어떻게 반복되는지 똑똑히 말해야 규칙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#10','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',3,'error','auto','지우가 🟥 🟦 🟦 🟥 🟦 🟦 를 보고 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_challenge#1','math',1,2,'u5','L02','g1_2_math_u5_L02_challenge','lesson_challenge','M1-2-u5-C1',2,'mc','auto','빈칸에 올 고깔은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X03']::text[],true,'{"seq":1,"concept":"M1-2-u5-C1","difficulty":2,"kind":"mc","stem":"빈칸에 올 고깔은 무엇인가요?","asset":{"type":"pattern_row","items":["🔶","🔺","🔺","🔶","🔺","🔺","🔶",null]},"options":[{"t":"🔺","correct":true},{"t":"🔶","mis":"M1-2-u5-X01"},{"t":"🟦","mis":"M1-2-u5-X03"}],"variant_rule":{"repeat":{"ask":"next","unit":[3,3],"pool":["🔶","🔺","🟦","⭐","🟢","🍎"]}},"explanation":["🔶, 🔺, 🔺 세 개가 한 덩이예요.","🔶 다음이니 🔺 가 와요.","처음부터 세 개씩 묶어 보면 차례가 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_challenge#2','math',1,2,'u5','L02','g1_2_math_u5_L02_challenge','lesson_challenge','M1-2-u5-C1',2,'sa','auto','🎈, 🪅, 🪅 가 되풀이되는 규칙으로 9개를 놓았어요. 🪅 는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u5-C1","difficulty":2,"kind":"sa","stem":"🎈, 🪅, 🪅 가 되풀이되는 규칙으로 9개를 놓았어요. 🪅 는 모두 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"pattern_row","items":["🎈","🪅","🪅","🎈","🪅","🪅","🎈","🪅","🪅"]},"answer":["6"],"variant_rule":{"repeat":{"ask":"count","unit":[3,3],"pool":["🎈","🪅","🎀","🎁"]}},"explanation":["한 덩이 🎈, 🪅, 🪅 에 🪅 가 2개 있어요.","9개면 덩이가 3개라 🪅 는 6개예요.","덩이 수와 덩이 안의 수를 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_challenge#3','math',1,2,'u5','L02','g1_2_math_u5_L02_challenge','lesson_challenge','M1-2-u5-C1',3,'mc','auto','곰 얼굴이 바로, 거꾸로 반복돼요. 빈칸 두 개에 순서대로 올 것은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X02']::text[],false,'{"seq":3,"concept":"M1-2-u5-C1","difficulty":3,"kind":"mc","stem":"곰 얼굴이 바로, 거꾸로 반복돼요. 빈칸 두 개에 순서대로 올 것은 무엇인가요?","asset":{"type":"pattern_row","items":["🐻","🙃","🐻","🙃","🐻","🙃",null,null]},"options":[{"t":"🐻, 🙃","correct":true},{"t":"🙃, 🐻","mis":"M1-2-u5-X01"},{"t":"🐻, 🐻","mis":"M1-2-u5-X02"}],"explanation":["🐻, 🙃 가 되풀이돼요.","🙃 다음은 🐻, 그다음은 🙃 예요.","빈칸이 둘이어도 차례대로 이어 가면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_challenge#4','math',1,2,'u5','L02','g1_2_math_u5_L02_challenge','lesson_challenge','M1-2-u5-C1',3,'ox','auto','연결 모형이 🟩 🟩 🟦 🟩 🟩 🟦 로 놓여 있어요. 개수가 2개, 1개로 반복됩니다.',ARRAY['M1-2-u5-X01']::text[],false,'{"seq":4,"concept":"M1-2-u5-C1","difficulty":3,"kind":"ox","stem":"연결 모형이 🟩 🟩 🟦 🟩 🟩 🟦 로 놓여 있어요. 개수가 2개, 1개로 반복됩니다.","asset":{"type":"pattern_row","items":["🟩","🟩","🟦","🟩","🟩","🟦"]},"answer":"O","reason_options":[{"t":"🟩 2개 다음 🟦 1개가 되풀이되니까","correct":true},{"t":"개수가 1개, 1개, 2개로 반복되니까","mis":"M1-2-u5-X01"}],"explanation":["🟩 🟩 🟦 가 한 덩이예요.","초록 2개, 파랑 1개가 되풀이돼요 — 맞아요.","색으로 말하면 초록, 초록, 파랑이 반복돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_challenge#5','math',1,2,'u5','L02','g1_2_math_u5_L02_challenge','lesson_challenge','M1-2-u5-C1',3,'mc','auto','🔶 🔺 🔶 🔺 에서 반복되는 부분에 묶음 표시를 바르게 한 것은 어느 것인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X02']::text[],false,'{"seq":5,"concept":"M1-2-u5-C1","difficulty":3,"kind":"mc","stem":"🔶 🔺 🔶 🔺 에서 반복되는 부분에 묶음 표시를 바르게 한 것은 어느 것인가요?","options":[{"t":"(🔶 🔺) (🔶 🔺)","correct":true},{"t":"🔶 (🔺 🔶) 🔺","mis":"M1-2-u5-X01"},{"t":"(🔶 🔺 🔶) (🔺)","mis":"M1-2-u5-X02"}],"explanation":["처음 그림부터 묶어요.","🔶, 🔺 두 개씩 묶으면 같은 덩이가 되풀이돼요.","묶음의 크기가 다르면 되풀이가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_challenge#6','math',1,2,'u5','L02','g1_2_math_u5_L02_challenge','lesson_challenge','M1-2-u5-C1',3,'error','auto','민수가 ↑ ↑ ↓ ↓ ↑ ↑ ↓ ↓ 를 보고 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_challenge#7','math',1,2,'u5','L02','g1_2_math_u5_L02_challenge','lesson_challenge','M1-2-u5-C1',3,'match','auto','그림과 반복되는 부분을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u5-C1","difficulty":3,"kind":"match","stem":"그림과 반복되는 부분을 선으로 이어 보세요.","pairs":[{"l":"🌸 🌺 🌺 🌸 🌺 🌺","r":"🌸, 🌺, 🌺"},{"l":"🌸 🌸 🌺 🌸 🌸 🌺","r":"🌸, 🌸, 🌺"},{"l":"🌸 🌺 🌸 🌺","r":"🌸, 🌺"}],"explanation":["처음부터 묶어 되풀이되는 부분을 찾아요.","같은 두 그림이라도 차례가 다르면 다른 규칙이에요.","🌸, 🌺, 🌺 와 🌸, 🌸, 🌺 는 서로 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_challenge#8','math',1,2,'u5','L02','g1_2_math_u5_L02_challenge','lesson_challenge','M1-2-u5-C1',4,'sa','auto','🔶, 🔺 가 되풀이되는 규칙으로 10개를 놓았어요. 🔺 는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M1-2-u5-C1","difficulty":4,"kind":"sa","stem":"🔶, 🔺 가 되풀이되는 규칙으로 10개를 놓았어요. 🔺 는 모두 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"pattern_row","items":["🔶","🔺","🔶","🔺","🔶","🔺","🔶","🔺","🔶","🔺"]},"answer":["5"],"variant_rule":{"repeat":{"ask":"count","unit":[2,2],"len":[8,10],"pool":["🔶","🔺","🟦","⭐","🟢","🍎"]}},"explanation":["한 덩이 🔶, 🔺 에 🔺 가 1개 있어요.","10개면 덩이가 5개라 🔺 는 5개예요.","덩이 수를 세면 전체 수를 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_challenge#9','math',1,2,'u5','L02','g1_2_math_u5_L02_challenge','lesson_challenge','M1-2-u5-C1',4,'mc','auto','🧴, 🩹, 🩹 가 되풀이되는 규칙으로 물건을 놓아요. 8번째에 놓을 물건은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X03']::text[],false,'{"seq":9,"concept":"M1-2-u5-C1","difficulty":4,"kind":"mc","stem":"🧴, 🩹, 🩹 가 되풀이되는 규칙으로 물건을 놓아요. 8번째에 놓을 물건은 무엇인가요?","options":[{"t":"🩹","correct":true},{"t":"🧴","mis":"M1-2-u5-X01"},{"t":"✂️","mis":"M1-2-u5-X03"}],"explanation":["🧴 🩹 🩹 🧴 🩹 🩹 🧴 🩹 — 8번째는 🩹 예요.","세 개씩 묶으면 7번째가 🧴 로 새 덩이가 시작돼요.","덩이의 첫째·둘째·셋째 자리를 세어 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_challenge#10','math',1,2,'u5','L02','g1_2_math_u5_L02_challenge','lesson_challenge','M1-2-u5-C1',4,'essay','teacher','🟥 🟦 🟦 🟥 🟦 🟦 ? ? 의 규칙을 말로 쓰고, 빈칸 두 개에 올 색과 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u5-C1","difficulty":4,"kind":"essay","stem":"🟥 🟦 🟦 🟥 🟦 🟦 ? ? 의 규칙을 말로 쓰고, 빈칸 두 개에 올 색과 그렇게 생각한 까닭을 쓰세요.","answer_guide":"① 「빨강, 파랑, 파랑이 반복돼요」 ② 빈칸은 🟥, 🟦 ③ 세 개씩 묶으면 7번째가 새 덩이의 첫째라는 까닭 — 셋 다 있으면 만점, 색만 쓰면 절반","explanation":["🟥, 🟦, 🟦 세 개가 한 덩이로 되풀이돼요.","두 덩이 다음이니 빈칸은 🟥, 🟦 예요.","무엇이 어떻게 반복되는지 말로 쓰면 규칙이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_basic#1','math',1,2,'u5','L03','g1_2_math_u5_L03_basic','lesson_basic','M1-2-u5-C2',1,'mc','auto','초록, 파랑, 파랑이 반복되는 규칙이에요. 빈칸에 올 색은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X04']::text[],true,'{"seq":1,"concept":"M1-2-u5-C2","difficulty":1,"kind":"mc","stem":"초록, 파랑, 파랑이 반복되는 규칙이에요. 빈칸에 올 색은 무엇인가요?","asset":{"type":"pattern_row","items":["🟩","🟦","🟦","🟩","🟦","🟦",null]},"options":[{"t":"🟩","correct":true},{"t":"🟦","mis":"M1-2-u5-X01"},{"t":"🟥","mis":"M1-2-u5-X04"}],"variant_rule":{"repeat":{"ask":"next","unit":[3,3],"pool":["🟩","🟦","🟥","🟨","🟪","🟧"]}},"explanation":["🟩, 🟦, 🟦 세 개가 한 덩이예요.","🟦, 🟦 다음이니 🟩 가 와요.","내가 정한 반복되는 부분을 그대로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_basic#2','math',1,2,'u5','L03','g1_2_math_u5_L03_basic','lesson_basic','M1-2-u5-C2',1,'sa','auto','풀, 지우개가 반복되는 규칙으로 6개를 놓았어요. 지우개는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u5-C2","difficulty":1,"kind":"sa","stem":"풀, 지우개가 반복되는 규칙으로 6개를 놓았어요. 지우개는 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"pattern_row","items":["🧴","🩹","🧴","🩹","🧴","🩹"]},"answer":["3"],"variant_rule":{"repeat":{"ask":"count","unit":[2,2],"pool":["🧴","🩹","✂️","✏️"]}},"explanation":["🧴, 🩹 가 한 덩이예요.","6개면 덩이가 3개라 🩹 는 3개예요.","전체에서 세어요 — 한 덩이 안의 1개가 답이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_basic#3','math',1,2,'u5','L03','g1_2_math_u5_L03_basic','lesson_basic','M1-2-u5-C2',1,'ox','auto','노랑, 파랑, 파랑 과 빨강, 초록, 초록 은 같은 규칙입니다.',ARRAY['M1-2-u5-X04']::text[],false,'{"seq":3,"concept":"M1-2-u5-C2","difficulty":1,"kind":"ox","stem":"노랑, 파랑, 파랑 과 빨강, 초록, 초록 은 같은 규칙입니다.","answer":"O","reason_options":[{"t":"반복되는 부분이 하나, 둘, 둘로 같으니까","correct":true},{"t":"색이 다르니까 다른 규칙이니까","mis":"M1-2-u5-X04"}],"explanation":["둘 다 「하나, 다른 것 둘」이 되풀이돼요.","색은 달라도 반복되는 부분이 같아서 같은 규칙이에요.","규칙은 무엇을 썼느냐가 아니라 어떻게 되풀이되느냐예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_basic#4','math',1,2,'u5','L03','g1_2_math_u5_L03_basic','lesson_basic','M1-2-u5-C2',1,'mc','auto','풀, 지우개가 반복되는 규칙으로 놓은 것은 어느 것인가요?',ARRAY['M1-2-u5-X02','M1-2-u5-X05']::text[],false,'{"seq":4,"concept":"M1-2-u5-C2","difficulty":1,"kind":"mc","stem":"풀, 지우개가 반복되는 규칙으로 놓은 것은 어느 것인가요?","options":[{"t":"🧴 🩹 🧴 🩹 🧴 🩹","correct":true},{"t":"🧴 🧴 🩹 🧴 🧴 🩹","mis":"M1-2-u5-X02"},{"t":"🧴 🩹 🩹 🧴 🩹 🧴","mis":"M1-2-u5-X05"}],"explanation":["🧴 다음 🩹, 그다음 다시 🧴 가 와야 해요.","🧴 🩹 두 개가 한 덩이로 되풀이돼요.","덩이가 흐트러지면 규칙이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_basic#5','math',1,2,'u5','L03','g1_2_math_u5_L03_basic','lesson_basic','M1-2-u5-C2',2,'mc','auto','🟥, 🟦 규칙과 🟥, 🟥, 🟦, 🟦 규칙은 색이 같아요. 두 규칙에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['M1-2-u5-X04','M1-2-u5-X05']::text[],false,'{"seq":5,"concept":"M1-2-u5-C2","difficulty":2,"kind":"mc","stem":"🟥, 🟦 규칙과 🟥, 🟥, 🟦, 🟦 규칙은 색이 같아요. 두 규칙에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"반복되는 부분이 달라서 다른 규칙이에요","correct":true},{"t":"색이 같으니 같은 규칙이에요","mis":"M1-2-u5-X04"},{"t":"둘 다 규칙이 아니에요","mis":"M1-2-u5-X05"}],"explanation":["🟥 🟦 는 두 개, 🟥 🟥 🟦 🟦 는 네 개가 한 덩이예요.","반복되는 부분이 다르면 다른 규칙이에요.","색만 바꾸는 게 아니라 반복되는 부분을 바꿔야 다른 규칙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_basic#6','math',1,2,'u5','L03','g1_2_math_u5_L03_basic','lesson_basic','M1-2-u5-C2',2,'match','auto','같은 규칙끼리 선으로 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"M1-2-u5-C2","difficulty":2,"kind":"match","stem":"같은 규칙끼리 선으로 이어 보세요.","pairs":[{"l":"🧴 🧴 ✂️ 🧴 🧴 ✂️","r":"⬛ ⬛ ⬜ ⬛ ⬛ ⬜"},{"l":"✏️ 🩹 ✏️ 🩹","r":"🔴 🔵 🔴 🔵"},{"l":"🪨 🪨 🌰 🌰","r":"🟥 🟥 🟨 🟨"}],"explanation":["물건은 달라도 반복되는 부분이 같으면 같은 규칙이에요.","둘, 하나 / 하나, 하나 / 둘, 둘 로 덩이를 견줘요.","규칙을 말로 바꿔 보면 짝이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_basic#7','math',1,2,'u5','L03','g1_2_math_u5_L03_basic','lesson_basic','M1-2-u5-C2',2,'sa','auto','초록, 파랑, 파랑 규칙으로 9개를 이었어요. 파랑은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M1-2-u5-C2","difficulty":2,"kind":"sa","stem":"초록, 파랑, 파랑 규칙으로 9개를 이었어요. 파랑은 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"pattern_row","items":["🟩","🟦","🟦","🟩","🟦","🟦","🟩","🟦","🟦"]},"answer":["6"],"variant_rule":{"repeat":{"ask":"count","unit":[3,3],"pool":["🟩","🟦","🟥","🟨","🟪","🟧"]}},"explanation":["한 덩이 🟩, 🟦, 🟦 에 🟦 가 2개 있어요.","9개면 덩이가 3개라 🟦 는 6개예요.","초록은 3개예요 — 둘을 더하면 9개."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_basic#8','math',1,2,'u5','L03','g1_2_math_u5_L03_basic','lesson_basic','M1-2-u5-C2',2,'mc','auto','네 친구가 자연물을 놓았어요. 규칙이 있는 것은 어느 것인가요?',ARRAY['M1-2-u5-X05']::text[],false,'{"seq":8,"concept":"M1-2-u5-C2","difficulty":2,"kind":"mc","stem":"네 친구가 자연물을 놓았어요. 규칙이 있는 것은 어느 것인가요?","options":[{"t":"🪨 🌰 🌰 🪨 🌰 🌰","correct":true},{"t":"🪨 🌰 🪨 🪨 🌰 🌰","mis":"M1-2-u5-X05"},{"t":"🌰 🪨 🪨 🌰 🪨 🌰","mis":"M1-2-u5-X05"}],"explanation":["🪨 🌰 🌰 가 두 번 되풀이돼요.","다른 둘은 같은 덩이가 되풀이되지 않아요.","되풀이되는 부분에 ○ 를 해 보면 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_basic#9','math',1,2,'u5','L03','g1_2_math_u5_L03_basic','lesson_basic','M1-2-u5-C2',2,'mc','auto','주사위 눈의 수를 2, 5 로 반복되게 놓았어요. 2, 5, 2, 5, 2 다음에 올 눈의 수는 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X02']::text[],false,'{"seq":9,"concept":"M1-2-u5-C2","difficulty":2,"kind":"mc","stem":"주사위 눈의 수를 2, 5 로 반복되게 놓았어요. 2, 5, 2, 5, 2 다음에 올 눈의 수는 무엇인가요?","options":[{"t":"5","correct":true},{"t":"2","mis":"M1-2-u5-X01"},{"t":"3","mis":"M1-2-u5-X02"}],"explanation":["2, 5 가 한 덩이예요.","2 다음이니 5가 와요.","눈의 수로도 규칙을 만들 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_basic#10','math',1,2,'u5','L03','g1_2_math_u5_L03_basic','lesson_basic','M1-2-u5-C2',3,'error','auto','민수가 친구의 「검정, 검정, 흰색」 규칙을 보고 풀, 가위, 가위 를 놓고 「같은 규칙이야」라고 했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_challenge#1','math',1,2,'u5','L03','g1_2_math_u5_L03_challenge','lesson_challenge','M1-2-u5-C2',2,'mc','auto','돌, 솔방울, 솔방울, 나뭇가지 규칙으로 놓았어요. 빈칸에 올 것은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X02']::text[],false,'{"seq":1,"concept":"M1-2-u5-C2","difficulty":2,"kind":"mc","stem":"돌, 솔방울, 솔방울, 나뭇가지 규칙으로 놓았어요. 빈칸에 올 것은 무엇인가요?","asset":{"type":"pattern_row","items":["🪨","🌰","🌰","🌿","🪨","🌰","🌰","🌿","🪨",null]},"options":[{"t":"🌰","correct":true},{"t":"🌿","mis":"M1-2-u5-X01"},{"t":"🪨","mis":"M1-2-u5-X02"}],"explanation":["🪨 🌰 🌰 🌿 네 개가 한 덩이예요.","🪨 다음이니 🌰 가 와요.","네 개씩 묶어 차례를 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_challenge#2','math',1,2,'u5','L03','g1_2_math_u5_L03_challenge','lesson_challenge','M1-2-u5-C2',2,'sa','auto','돌, 솔방울, 솔방울, 나뭇가지 규칙으로 8개를 놓았어요. 솔방울은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M1-2-u5-C2","difficulty":2,"kind":"sa","stem":"돌, 솔방울, 솔방울, 나뭇가지 규칙으로 8개를 놓았어요. 솔방울은 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"pattern_row","items":["🪨","🌰","🌰","🌿","🪨","🌰","🌰","🌿"]},"answer":["4"],"explanation":["한 덩이에 🌰 가 2개 있어요.","8개면 덩이가 2개라 🌰 는 4개예요.","덩이 수 × 덩이 안의 수로 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_challenge#3','math',1,2,'u5','L03','g1_2_math_u5_L03_challenge','lesson_challenge','M1-2-u5-C2',3,'ox','auto','노랑, 파랑, 파랑 과 노랑, 노랑, 파랑 은 같은 규칙입니다.',ARRAY['M1-2-u5-X04']::text[],false,'{"seq":3,"concept":"M1-2-u5-C2","difficulty":3,"kind":"ox","stem":"노랑, 파랑, 파랑 과 노랑, 노랑, 파랑 은 같은 규칙입니다.","answer":"X","reason_options":[{"t":"하나, 둘 과 둘, 하나 로 반복되는 부분의 차례가 다르니까","correct":true},{"t":"같은 두 색을 썼으니까","mis":"M1-2-u5-X04"}],"explanation":["노랑, 파랑, 파랑 은 「하나, 둘」이에요.","노랑, 노랑, 파랑 은 「둘, 하나」라 차례가 달라요.","같은 색을 써도 반복되는 부분이 다르면 다른 규칙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_challenge#4','math',1,2,'u5','L03','g1_2_math_u5_L03_challenge','lesson_challenge','M1-2-u5-C2',3,'mc','auto','초록, 파랑, 파랑 규칙으로 9개를 이었어요. 초록과 파랑은 각각 몇 개인가요?',ARRAY['M1-2-u5-X11','M1-2-u5-X01']::text[],false,'{"seq":4,"concept":"M1-2-u5-C2","difficulty":3,"kind":"mc","stem":"초록, 파랑, 파랑 규칙으로 9개를 이었어요. 초록과 파랑은 각각 몇 개인가요?","options":[{"t":"🟩 3개, 🟦 6개","correct":true},{"t":"🟩 1개, 🟦 2개","mis":"M1-2-u5-X11"},{"t":"🟩 6개, 🟦 3개","mis":"M1-2-u5-X01"}],"explanation":["한 덩이에 🟩 1개, 🟦 2개예요.","덩이가 3개라 🟩 3개, 🟦 6개예요.","1개, 2개는 한 덩이 안의 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_challenge#5','math',1,2,'u5','L03','g1_2_math_u5_L03_challenge','lesson_challenge','M1-2-u5-C2',3,'mc','auto','친구가 ⬛ ⬛ ⬜ 규칙을 만들었어요. 같은 규칙으로 내 물건을 놓은 것은 어느 것인가요?',ARRAY['M1-2-u5-X02','M1-2-u5-X05']::text[],false,'{"seq":5,"concept":"M1-2-u5-C2","difficulty":3,"kind":"mc","stem":"친구가 ⬛ ⬛ ⬜ 규칙을 만들었어요. 같은 규칙으로 내 물건을 놓은 것은 어느 것인가요?","options":[{"t":"🧴 🧴 ✂️ 🧴 🧴 ✂️","correct":true},{"t":"🧴 ✂️ ✂️ 🧴 ✂️ ✂️","mis":"M1-2-u5-X02"},{"t":"🧴 🧴 🧴 ✂️ ✂️ ✂️","mis":"M1-2-u5-X05"}],"explanation":["⬛ ⬛ ⬜ 는 「둘, 하나」예요.","🧴 🧴 ✂️ 도 「둘, 하나」라 같은 규칙이에요.","🧴 ✂️ ✂️ 는 「하나, 둘」이라 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_challenge#6','math',1,2,'u5','L03','g1_2_math_u5_L03_challenge','lesson_challenge','M1-2-u5-C2',3,'error','auto','지우가 🔴 🔵 🔵 🔴 🔵 🔴 를 놓고 「🔴, 🔵, 🔵 규칙이야」라고 했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_challenge#7','math',1,2,'u5','L03','g1_2_math_u5_L03_challenge','lesson_challenge','M1-2-u5-C2',3,'match','auto','규칙을 말한 것과 물건으로 놓은 것을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u5-C2","difficulty":3,"kind":"match","stem":"규칙을 말한 것과 물건으로 놓은 것을 선으로 이어 보세요.","pairs":[{"l":"돌, 돌, 솔방울","r":"🪨 🪨 🌰 🪨 🪨 🌰"},{"l":"풀, 가위, 가위","r":"🧴 ✂️ ✂️ 🧴 ✂️ ✂️"},{"l":"연필, 지우개","r":"✏️ 🩹 ✏️ 🩹"}],"explanation":["말한 차례대로 물건을 놓아요.","「둘, 하나」·「하나, 둘」·「하나, 하나」를 구별해요.","내가 만든 규칙은 말로 설명할 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_challenge#8','math',1,2,'u5','L03','g1_2_math_u5_L03_challenge','lesson_challenge','M1-2-u5-C2',4,'sa','auto','풀, 지우개, 지우개 규칙으로 12개를 놓았어요. 지우개는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u5-C2","difficulty":4,"kind":"sa","stem":"풀, 지우개, 지우개 규칙으로 12개를 놓았어요. 지우개는 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 덩이 🧴 🩹 🩹 에 🩹 가 2개예요.","12개면 덩이가 4개라 🩹 는 8개예요.","풀은 4개 — 둘을 더하면 12개."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_challenge#9','math',1,2,'u5','L03','g1_2_math_u5_L03_challenge','lesson_challenge','M1-2-u5-C2',4,'mc','auto','🟥, 🟦 규칙으로 10개를 놓았어요. 같은 두 색으로 다른 규칙을 만들려면 어떻게 해야 하나요?',ARRAY['M1-2-u5-X01','M1-2-u5-X04']::text[],false,'{"seq":9,"concept":"M1-2-u5-C2","difficulty":4,"kind":"mc","stem":"🟥, 🟦 규칙으로 10개를 놓았어요. 같은 두 색으로 다른 규칙을 만들려면 어떻게 해야 하나요?","options":[{"t":"🟥, 🟥, 🟦 처럼 반복되는 부분을 바꿔요","correct":true},{"t":"🟦, 🟥 로 자리만 바꿔요","mis":"M1-2-u5-X01"},{"t":"색을 🟩, 🟨 으로 바꿔요","mis":"M1-2-u5-X04"}],"explanation":["다른 규칙은 반복되는 부분이 달라야 해요.","🟥 🟥 🟦 는 「둘, 하나」라 🟥 🟦 와 달라요.","🟦 🟥 은 같은 덩이의 시작만 다른 것이고, 색만 바꾸면 같은 규칙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L03_challenge#10','math',1,2,'u5','L03','g1_2_math_u5_L03_challenge','lesson_challenge','M1-2-u5-C2',4,'essay','teacher','두 가지 물건으로 규칙을 하나 만들어 8개를 놓으세요. 반복되는 부분을 말로 쓰고, 두 물건이 각각 몇 개인지도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u5-C2","difficulty":4,"kind":"essay","stem":"두 가지 물건으로 규칙을 하나 만들어 8개를 놓으세요. 반복되는 부분을 말로 쓰고, 두 물건이 각각 몇 개인지도 쓰세요.","answer_guide":"① 반복되는 부분(예: 풀, 풀, 가위) ② 8개를 규칙대로 쓴 것 ③ 각 물건의 개수(예: 풀 6, 가위 2 → 8개 중 덩이 2개 + 남은 2개) — 셋 다 맞으면 만점, 규칙만 쓰면 절반","explanation":["반복되는 부분을 먼저 정해요.","정한 부분을 되풀이해 8개를 놓아요.","전체에서 각 물건을 세면 개수가 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_basic#1','math',1,2,'u5','L04','g1_2_math_u5_L04_basic','lesson_basic','M1-2-u5-C3',1,'mc','auto','가방 무늬예요. 둘째 줄의 빈칸에 올 색은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X05']::text[],false,'{"seq":1,"concept":"M1-2-u5-C3","difficulty":1,"kind":"mc","stem":"가방 무늬예요. 둘째 줄의 빈칸에 올 색은 무엇인가요?","asset":{"type":"pattern_grid","rows":[["🟨","🟦","🟨","🟦"],["🟦","🟨","🟦",null]]},"options":[{"t":"🟨","correct":true},{"t":"🟦","mis":"M1-2-u5-X01"},{"t":"🟥","mis":"M1-2-u5-X05"}],"explanation":["첫째 줄은 🟨, 🟦 가 반복돼요.","둘째 줄은 🟦, 🟨 가 반복되니 빈칸은 🟨 예요.","네 칸이 한 덩이가 되어 되풀이돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_basic#2','math',1,2,'u5','L04','g1_2_math_u5_L04_basic','lesson_basic','M1-2-u5-C3',1,'mc','auto','네모, 별, 별이 반복되는 무늬예요. 빈칸에 올 모양은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X05']::text[],true,'{"seq":2,"concept":"M1-2-u5-C3","difficulty":1,"kind":"mc","stem":"네모, 별, 별이 반복되는 무늬예요. 빈칸에 올 모양은 무엇인가요?","asset":{"type":"pattern_row","items":["■","★","★","■","★","★",null]},"options":[{"t":"■","correct":true},{"t":"★","mis":"M1-2-u5-X01"},{"t":"●","mis":"M1-2-u5-X05"}],"variant_rule":{"repeat":{"ask":"next","unit":[3,3],"pool":["■","★","●","◆","☾"]}},"explanation":["■, ★, ★ 세 개가 한 덩이예요.","★, ★ 다음이니 ■ 가 와요.","고른 두 모양만 되풀이해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_basic#3','math',1,2,'u5','L04','g1_2_math_u5_L04_basic','lesson_basic','M1-2-u5-C3',1,'sa','auto','별, 동그라미가 반복되는 무늬를 8칸 꾸몄어요. 별은 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-2-u5-C3","difficulty":1,"kind":"sa","stem":"별, 동그라미가 반복되는 무늬를 8칸 꾸몄어요. 별은 몇 칸인가요? 숫자로 쓰세요.","asset":{"type":"pattern_row","items":["★","●","★","●","★","●","★","●"]},"answer":["4"],"variant_rule":{"repeat":{"ask":"count","unit":[2,2],"pool":["■","★","●","◆","☾"]}},"explanation":["★, ● 가 한 덩이예요.","8칸이면 덩이가 4개라 ★ 는 4칸이에요.","동그라미도 4칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_basic#4','math',1,2,'u5','L04','g1_2_math_u5_L04_basic','lesson_basic','M1-2-u5-C3',1,'ox','auto','두 가지 모양을 골라 번갈아 놓으면 규칙이 있는 무늬입니다.',ARRAY['M1-2-u5-X05']::text[],false,'{"seq":4,"concept":"M1-2-u5-C3","difficulty":1,"kind":"ox","stem":"두 가지 모양을 골라 번갈아 놓으면 규칙이 있는 무늬입니다.","answer":"O","reason_options":[{"t":"두 모양이 되풀이되니까","correct":true},{"t":"모양을 마음대로 놓아도 규칙이 있으니까","mis":"M1-2-u5-X05"}],"explanation":["★ ● ★ ● 처럼 번갈아 놓으면 ★, ● 가 되풀이돼요.","되풀이되는 부분이 있으면 규칙 있는 무늬예요.","마음대로 놓으면 되풀이가 없어 규칙이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_basic#5','math',1,2,'u5','L04','g1_2_math_u5_L04_basic','lesson_basic','M1-2-u5-C3',2,'match','auto','무늬와 규칙을 선으로 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"M1-2-u5-C3","difficulty":2,"kind":"match","stem":"무늬와 규칙을 선으로 이어 보세요.","pairs":[{"l":"★ ● ★ ●","r":"별, 동그라미가 반복돼요"},{"l":"■ ★ ★ ■ ★ ★","r":"네모, 별, 별이 반복돼요"},{"l":"● ● ★ ★","r":"동그라미, 동그라미, 별, 별이 반복돼요"}],"explanation":["처음부터 되풀이되는 부분을 묶어요.","두 개·세 개·네 개 덩이를 구별해요.","무늬를 말로 바꾸면 규칙이 또렷해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_basic#6','math',1,2,'u5','L04','g1_2_math_u5_L04_basic','lesson_basic','M1-2-u5-C3',2,'mc','auto','네모, 별, 별 규칙으로 꾸민 무늬는 어느 것인가요?',ARRAY['M1-2-u5-X05','M1-2-u5-X02']::text[],false,'{"seq":6,"concept":"M1-2-u5-C3","difficulty":2,"kind":"mc","stem":"네모, 별, 별 규칙으로 꾸민 무늬는 어느 것인가요?","options":[{"t":"■ ★ ★ ■ ★ ★","correct":true},{"t":"■ ★ ■ ★ ★ ■","mis":"M1-2-u5-X05"},{"t":"■ ■ ★ ■ ■ ★","mis":"M1-2-u5-X02"}],"explanation":["■ ★ ★ 가 두 번 되풀이돼요.","■ ★ ■ ★ ★ ■ 는 덩이가 흐트러졌어요.","■ ■ ★ 은 「둘, 하나」라 다른 규칙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_basic#7','math',1,2,'u5','L04','g1_2_math_u5_L04_basic','lesson_basic','M1-2-u5-C3',2,'sa','auto','보라, 초록 규칙으로 꾸민 꽃무늬예요. 보라는 모두 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u5-C3","difficulty":2,"kind":"sa","stem":"보라, 초록 규칙으로 꾸민 꽃무늬예요. 보라는 모두 몇 칸인가요? 숫자로 쓰세요.","asset":{"type":"pattern_grid","rows":[["🟪","🟩","🟪","🟩"],["🟩","🟪","🟩","🟪"],["🟪","🟩","🟪","🟩"],["🟩","🟪","🟩","🟪"]]},"answer":["8"],"explanation":["한 줄에 🟪 가 2칸이에요.","네 줄이라 🟪 는 8칸이에요.","초록도 8칸 — 모두 16칸."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_basic#8','math',1,2,'u5','L04','g1_2_math_u5_L04_basic','lesson_basic','M1-2-u5-C3',2,'mc','auto','둘째 줄은 동그라미, 별이 반복돼요. 빈칸 두 개에 순서대로 올 모양은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X02']::text[],false,'{"seq":8,"concept":"M1-2-u5-C3","difficulty":2,"kind":"mc","stem":"둘째 줄은 동그라미, 별이 반복돼요. 빈칸 두 개에 순서대로 올 모양은 무엇인가요?","asset":{"type":"pattern_grid","rows":[["★","●","★","●"],["●","★",null,null]]},"options":[{"t":"●, ★","correct":true},{"t":"★, ●","mis":"M1-2-u5-X01"},{"t":"●, ●","mis":"M1-2-u5-X02"}],"explanation":["둘째 줄은 ●, ★ 가 되풀이돼요.","●, ★ 다음이니 다시 ●, ★ 예요.","첫째 줄과 둘째 줄은 순서가 반대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_basic#9','math',1,2,'u5','L04','g1_2_math_u5_L04_basic','lesson_basic','M1-2-u5-C3',2,'ox','auto','가방 무늬처럼 둘째 줄의 순서가 첫째 줄과 반대여도 규칙이 있는 무늬입니다.',ARRAY['M1-2-u5-X05']::text[],false,'{"seq":9,"concept":"M1-2-u5-C3","difficulty":2,"kind":"ox","stem":"가방 무늬처럼 둘째 줄의 순서가 첫째 줄과 반대여도 규칙이 있는 무늬입니다.","asset":{"type":"pattern_grid","rows":[["🟨","🟦","🟨","🟦"],["🟦","🟨","🟦","🟨"]]},"answer":"O","reason_options":[{"t":"네 칸이 한 덩이가 되어 되풀이되니까","correct":true},{"t":"줄마다 순서가 다르면 규칙이 아니니까","mis":"M1-2-u5-X05"}],"explanation":["첫째 줄 🟨 🟦, 둘째 줄 🟦 🟨 가 한 덩이예요.","그 덩이가 되풀이되니 규칙 있는 무늬예요.","줄을 넘어서도 되풀이되는 부분을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_basic#10','math',1,2,'u5','L04','g1_2_math_u5_L04_basic','lesson_basic','M1-2-u5-C3',3,'error','auto','지우가 가방 무늬(첫째 줄 🟨 🟦, 둘째 줄 🟦 🟨)의 셋째 줄에 🟦 🟨 🟦 🟨 를 칠했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_challenge#1','math',1,2,'u5','L04','g1_2_math_u5_L04_challenge','lesson_challenge','M1-2-u5-C3',2,'mc','auto','마름모, 동그라미, 동그라미가 반복되는 무늬예요. 빈칸에 올 모양은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X05']::text[],true,'{"seq":1,"concept":"M1-2-u5-C3","difficulty":2,"kind":"mc","stem":"마름모, 동그라미, 동그라미가 반복되는 무늬예요. 빈칸에 올 모양은 무엇인가요?","asset":{"type":"pattern_row","items":["◆","●","●","◆","●","●","◆",null]},"options":[{"t":"●","correct":true},{"t":"◆","mis":"M1-2-u5-X01"},{"t":"★","mis":"M1-2-u5-X05"}],"variant_rule":{"repeat":{"ask":"next","unit":[3,3],"pool":["■","★","●","◆","☾"]}},"explanation":["◆, ●, ● 세 개가 한 덩이예요.","◆ 다음이니 ● 가 와요.","고른 두 모양으로만 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_challenge#2','math',1,2,'u5','L04','g1_2_math_u5_L04_challenge','lesson_challenge','M1-2-u5-C3',2,'sa','auto','가방 무늬를 네 줄 완성했어요. 파란색은 모두 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M1-2-u5-C3","difficulty":2,"kind":"sa","stem":"가방 무늬를 네 줄 완성했어요. 파란색은 모두 몇 칸인가요? 숫자로 쓰세요.","asset":{"type":"pattern_grid","rows":[["🟨","🟦","🟨","🟦"],["🟦","🟨","🟦","🟨"],["🟨","🟦","🟨","🟦"],["🟦","🟨","🟦","🟨"]]},"answer":["8"],"explanation":["한 줄에 🟦 가 2칸이에요.","네 줄이라 🟦 는 8칸이에요.","노란색도 8칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_challenge#3','math',1,2,'u5','L04','g1_2_math_u5_L04_challenge','lesson_challenge','M1-2-u5-C3',3,'mc','auto','모양 다섯 가지 가운데 두 가지를 골라 만든 규칙 있는 무늬는 어느 것인가요?',ARRAY['M1-2-u5-X05']::text[],false,'{"seq":3,"concept":"M1-2-u5-C3","difficulty":3,"kind":"mc","stem":"모양 다섯 가지 가운데 두 가지를 골라 만든 규칙 있는 무늬는 어느 것인가요?","options":[{"t":"☾ ◆ ☾ ◆ ☾ ◆","correct":true},{"t":"☾ ◆ ◆ ☾ ☾ ◆","mis":"M1-2-u5-X05"},{"t":"☾ ☾ ☾ ☾ ☾ ☾","mis":"M1-2-u5-X05"}],"explanation":["☾, ◆ 가 되풀이돼요.","☾ ◆ ◆ ☾ ☾ ◆ 는 같은 덩이가 되풀이되지 않아요.","한 가지 모양만 놓으면 되풀이되는 부분이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_challenge#4','math',1,2,'u5','L04','g1_2_math_u5_L04_challenge','lesson_challenge','M1-2-u5-C3',3,'ox','auto','■, ★, ★ 규칙과 ●, ◆, ◆ 규칙은 같은 규칙입니다.',ARRAY['M1-2-u5-X04']::text[],false,'{"seq":4,"concept":"M1-2-u5-C3","difficulty":3,"kind":"ox","stem":"■, ★, ★ 규칙과 ●, ◆, ◆ 규칙은 같은 규칙입니다.","answer":"O","reason_options":[{"t":"하나, 둘로 반복되는 부분이 같으니까","correct":true},{"t":"모양이 다르니까 다른 규칙이니까","mis":"M1-2-u5-X04"}],"explanation":["둘 다 「하나, 둘」이 되풀이돼요.","모양은 달라도 반복되는 부분이 같아 같은 규칙이에요.","규칙은 어떻게 되풀이되느냐로 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_challenge#5','math',1,2,'u5','L04','g1_2_math_u5_L04_challenge','lesson_challenge','M1-2-u5-C3',3,'mc','auto','별, 동그라미 무늬를 세 줄 꾸몄어요. 셋째 줄 빈칸에 올 모양은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X05']::text[],false,'{"seq":5,"concept":"M1-2-u5-C3","difficulty":3,"kind":"mc","stem":"별, 동그라미 무늬를 세 줄 꾸몄어요. 셋째 줄 빈칸에 올 모양은 무엇인가요?","asset":{"type":"pattern_grid","rows":[["★","●","★","●"],["●","★","●","★"],["★","●","★",null]]},"options":[{"t":"●","correct":true},{"t":"★","mis":"M1-2-u5-X01"},{"t":"■","mis":"M1-2-u5-X05"}],"explanation":["첫째 줄 ★ ●, 둘째 줄 ● ★ 가 한 덩이예요.","셋째 줄은 첫째 줄과 같은 ★ ● 라 빈칸은 ● 예요.","두 줄 덩이가 되풀이돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_challenge#6','math',1,2,'u5','L04','g1_2_math_u5_L04_challenge','lesson_challenge','M1-2-u5-C3',3,'error','auto','민수가 ■ ★ ★ ■ ★ ■ 를 놓고 「네모, 별, 별 규칙으로 꾸몄어」라고 했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_challenge#7','math',1,2,'u5','L04','g1_2_math_u5_L04_challenge','lesson_challenge','M1-2-u5-C3',3,'match','auto','첫째 줄과 순서가 반대인 둘째 줄을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u5-C3","difficulty":3,"kind":"match","stem":"첫째 줄과 순서가 반대인 둘째 줄을 선으로 이어 보세요.","pairs":[{"l":"🟨 🟦 🟨 🟦","r":"🟦 🟨 🟦 🟨"},{"l":"🟥 🟩 🟩 🟥 🟩 🟩","r":"🟩 🟥 🟥 🟩 🟥 🟥"},{"l":"★ ● ★ ●","r":"● ★ ● ★"}],"explanation":["둘째 줄은 첫째 줄의 색·모양 자리를 서로 바꿔요.","「하나, 둘」은 「둘, 하나」가 돼요.","두 줄이 한 덩이가 되어 되풀이돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_challenge#8','math',1,2,'u5','L04','g1_2_math_u5_L04_challenge','lesson_challenge','M1-2-u5-C3',4,'sa','auto','★, ●, ● 규칙으로 12칸 무늬를 꾸미면 ● 는 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u5-C3","difficulty":4,"kind":"sa","stem":"★, ●, ● 규칙으로 12칸 무늬를 꾸미면 ● 는 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 덩이 ★ ● ● 에 ● 가 2칸이에요.","12칸이면 덩이가 4개라 ● 는 8칸이에요.","★ 는 4칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_challenge#9','math',1,2,'u5','L04','g1_2_math_u5_L04_challenge','lesson_challenge','M1-2-u5-C3',4,'mc','auto','가방 무늬(첫째 줄 🟨 🟦 🟨 🟦, 둘째 줄 🟦 🟨 🟦 🟨)를 네 줄 만들면 🟦 는 몇 칸인가요?',ARRAY['M1-2-u5-X11','M1-2-u5-X02']::text[],false,'{"seq":9,"concept":"M1-2-u5-C3","difficulty":4,"kind":"mc","stem":"가방 무늬(첫째 줄 🟨 🟦 🟨 🟦, 둘째 줄 🟦 🟨 🟦 🟨)를 네 줄 만들면 🟦 는 몇 칸인가요?","options":[{"t":"8","correct":true},{"t":"4","mis":"M1-2-u5-X11"},{"t":"16","mis":"M1-2-u5-X02"}],"explanation":["한 줄에 🟦 가 2칸이에요.","네 줄이라 🟦 는 8칸이에요.","4는 한 덩이(두 줄) 안의 수, 16은 전체 칸 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L04_challenge#10','math',1,2,'u5','L04','g1_2_math_u5_L04_challenge','lesson_challenge','M1-2-u5-C3',4,'essay','teacher','두 가지 모양을 골라 나만의 규칙으로 여섯 칸 무늬를 꾸미고(모양 이름으로 쓰기), 규칙을 말로 쓰세요. 둘째 줄을 첫째 줄과 반대로 만들면 어떻게 되는지도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u5-C3","difficulty":4,"kind":"essay","stem":"두 가지 모양을 골라 나만의 규칙으로 여섯 칸 무늬를 꾸미고(모양 이름으로 쓰기), 규칙을 말로 쓰세요. 둘째 줄을 첫째 줄과 반대로 만들면 어떻게 되는지도 쓰세요.","answer_guide":"① 두 모양으로 6칸 무늬 ② 「○, ○가 반복돼요」 규칙 문장 ③ 둘째 줄 = 첫째 줄 자리 바꿈 — 셋 다 있으면 만점, 무늬만 쓰면 절반","explanation":["두 모양을 골라 반복되는 부분을 만들어요.","그 부분을 되풀이해 여섯 칸을 채워요.","둘째 줄은 자리를 바꿔 반대로 놓아도 규칙 있는 무늬예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L05_basic#1','math',1,2,'u5','L05','g1_2_math_u5_L05_basic','lesson_basic','M1-2-u5-C4',1,'mc','auto','기차 칸의 수예요. 3, 7 이 되풀이돼요. 빈칸에 올 수는 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X06']::text[],true,'{"seq":1,"concept":"M1-2-u5-C4","difficulty":1,"kind":"mc","stem":"기차 칸의 수예요. 3, 7 이 되풀이돼요. 빈칸에 올 수는 무엇인가요?","asset":{"type":"number_line","cells":[3,7,3,7,3,null]},"options":[{"t":"7","correct":true},{"t":"3","mis":"M1-2-u5-X01"},{"t":"8","mis":"M1-2-u5-X06"}],"variant_rule":{"numrule":{"kind":"repeat"}},"explanation":["3, 7 이 한 덩이예요.","3 다음이니 7이에요.","수도 되풀이될 수 있어요 — 커지는 규칙이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L05_basic#2','math',1,2,'u5','L05','g1_2_math_u5_L05_basic','lesson_basic','M1-2-u5-C4',1,'sa','auto','번호판의 수예요. 4, 4, 9 가 되풀이돼요. 빈칸에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u5-C4","difficulty":1,"kind":"sa","stem":"번호판의 수예요. 4, 4, 9 가 되풀이돼요. 빈칸에 알맞은 수를 쓰세요.","asset":{"type":"number_line","cells":[4,4,9,4,4,null,4,4,9]},"answer":["9"],"variant_rule":{"numrule":{"kind":"repeat"}},"explanation":["4, 4, 9 세 개가 한 덩이예요.","4, 4 다음이니 9예요.","처음부터 세 개씩 묶어 차례를 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L05_basic#3','math',1,2,'u5','L05','g1_2_math_u5_L05_basic','lesson_basic','M1-2-u5-C4',1,'sa','auto','풍선의 수예요. 15부터 시작하여 1씩 커져요. 빈칸에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-2-u5-C4","difficulty":1,"kind":"sa","stem":"풍선의 수예요. 15부터 시작하여 1씩 커져요. 빈칸에 알맞은 수를 쓰세요.","asset":{"type":"number_line","cells":[15,16,null,18,19,20]},"answer":["17"],"variant_rule":{"numrule":{"kind":"skip","step":[1,1],"dir":"up"}},"explanation":["15, 16 다음이니 1 큰 17이에요.","옆의 수와 1씩 차이가 나요.","「15부터 시작하여 1씩 커져요」라고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L05_basic#4','math',1,2,'u5','L05','g1_2_math_u5_L05_basic','lesson_basic','M1-2-u5-C4',1,'mc','auto','1, 3, 5, 7, 9 는 몇씩 커지나요?',ARRAY['M1-2-u5-X06']::text[],false,'{"seq":4,"concept":"M1-2-u5-C4","difficulty":1,"kind":"mc","stem":"1, 3, 5, 7, 9 는 몇씩 커지나요?","options":[{"t":"2","correct":true},{"t":"1","mis":"M1-2-u5-X06"},{"t":"3","mis":"M1-2-u5-X06"}],"explanation":["1에서 3, 3에서 5 — 옆의 수와 2 차이가 나요.","그래서 2씩 커져요.","뛰어 세기로 차이를 재요 — 늘 1씩은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L05_basic#5','math',1,2,'u5','L05','g1_2_math_u5_L05_basic','lesson_basic','M1-2-u5-C4',2,'match','auto','수 배열과 규칙을 선으로 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"M1-2-u5-C4","difficulty":2,"kind":"match","stem":"수 배열과 규칙을 선으로 이어 보세요.","pairs":[{"l":"10, 11, 12, 13","r":"10부터 1씩 커져요"},{"l":"2, 4, 6, 8","r":"2부터 2씩 커져요"},{"l":"20, 18, 16, 14","r":"20부터 2씩 작아져요"}],"explanation":["처음 수와 옆의 수와의 차이를 봐요.","커지는지 작아지는지 방향도 봐요.","「몇부터 시작하여 몇씩」이라고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L05_basic#6','math',1,2,'u5','L05','g1_2_math_u5_L05_basic','lesson_basic','M1-2-u5-C4',2,'mc','auto','의자의 수예요. 28부터 시작하여 2씩 작아져요. 빈칸에 올 수는 무엇인가요?',ARRAY['M1-2-u5-X07','M1-2-u5-X06']::text[],true,'{"seq":6,"concept":"M1-2-u5-C4","difficulty":2,"kind":"mc","stem":"의자의 수예요. 28부터 시작하여 2씩 작아져요. 빈칸에 올 수는 무엇인가요?","asset":{"type":"number_line","cells":[28,26,24,null,20,18]},"options":[{"t":"22","correct":true},{"t":"26","mis":"M1-2-u5-X07"},{"t":"23","mis":"M1-2-u5-X06"}],"variant_rule":{"numrule":{"kind":"skip","step":[2,2],"dir":"down"}},"explanation":["28, 26, 24 — 2씩 작아져요.","24보다 2 작은 22예요.","26은 커진다고 본 답, 23은 1씩으로 본 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L05_basic#7','math',1,2,'u5','L05','g1_2_math_u5_L05_basic','lesson_basic','M1-2-u5-C4',2,'sa','auto','번호판의 수예요. 1, 1, 6 이 되풀이돼요. 빈칸에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M1-2-u5-C4","difficulty":2,"kind":"sa","stem":"번호판의 수예요. 1, 1, 6 이 되풀이돼요. 빈칸에 알맞은 수를 쓰세요.","asset":{"type":"number_line","cells":[1,1,6,1,1,null,1,1,6]},"answer":["6"],"variant_rule":{"numrule":{"kind":"repeat"}},"explanation":["1, 1, 6 세 개가 한 덩이예요.","1, 1 다음이니 6이에요.","「1, 6, 1」이 아니라 처음부터 「1, 1, 6」으로 묶어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L05_basic#8','math',1,2,'u5','L05','g1_2_math_u5_L05_basic','lesson_basic','M1-2-u5-C4',2,'ox','auto','1, 1, 6, 1, 1, 6 은 1부터 시작하여 1씩 커지는 규칙입니다.',ARRAY['M1-2-u5-X06']::text[],false,'{"seq":8,"concept":"M1-2-u5-C4","difficulty":2,"kind":"ox","stem":"1, 1, 6, 1, 1, 6 은 1부터 시작하여 1씩 커지는 규칙입니다.","answer":"X","reason_options":[{"t":"1, 1, 6 이 되풀이되니까","correct":true},{"t":"1 다음에 6이 나와 수가 커지니까","mis":"M1-2-u5-X06"}],"explanation":["1, 1, 6 다음에 다시 1, 1, 6 이 와요.","수가 커지는 게 아니라 되풀이되는 규칙이에요.","되풀이되는 수와 커지는 수를 구별해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L05_basic#9','math',1,2,'u5','L05','g1_2_math_u5_L05_basic','lesson_basic','M1-2-u5-C4',2,'mc','auto','5, 7, 7 이 되풀이되는 규칙이에요. 5, 7, 7, 5, 7, 7, □, 7, 7 — □에 올 수는 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X06']::text[],true,'{"seq":9,"concept":"M1-2-u5-C4","difficulty":2,"kind":"mc","stem":"5, 7, 7 이 되풀이되는 규칙이에요. 5, 7, 7, 5, 7, 7, □, 7, 7 — □에 올 수는 무엇인가요?","options":[{"t":"5","correct":true},{"t":"7","mis":"M1-2-u5-X01"},{"t":"9","mis":"M1-2-u5-X06"}],"variant_rule":{"numrule":{"kind":"repeat"}},"explanation":["5, 7, 7 이 한 덩이예요.","두 덩이 다음이니 새 덩이의 처음 5예요.","커지는 규칙이 아니라 되풀이 규칙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
